<script lang="ts">
import {untrack} from "svelte";
import CourseText from "./CourseText.svelte";
import CourseAudio from "./CourseAudio.svelte";
import type {CourseAction,CourseActionResult,PublicCourseLesson,CourseProgress,CourseSentence} from "../../types/course";
let {showTransliteration=true,lesson,progress,feedback,busy,act,startIndex=0,inspected=false,onSupportUsed,onPosition}:{showTransliteration?:boolean;lesson:PublicCourseLesson;progress:CourseProgress;feedback:Record<string,NonNullable<CourseActionResult["feedback"]>>;busy:boolean;act:(a:CourseAction)=>Promise<CourseActionResult|undefined>;startIndex?:number;inspected?:boolean;onSupportUsed:()=>void;onPosition:(index:number)=>void}=$props();
let exerciseIndex=$state(0);
let submitting=$state(false);let retrying=$state<Record<string,boolean>>({});
$effect(()=>{exerciseIndex=startIndex;});
$effect(()=>{onPosition(exerciseIndex);});
let currentExercise=$derived(lesson.exercises[exerciseIndex]);
let language=$derived(lesson.language);let isArabic=$derived(language==="ar-EG");
let transliterationUsed=$state(false);$effect(()=>{if(isArabic&&showTransliteration){transliterationUsed=true;onSupportUsed();}});
let drafts=$state<Record<string,string>>({});let tokenSelections=$state<Record<string,number[]>>({});let matches=$state<Record<string,Record<string,string>>>({});
let currentResult=$derived(retrying[currentExercise?.id]?undefined:feedback[currentExercise?.id]);
let submitted=$derived(!!progress.exercises[currentExercise?.id]?.attempts.length&&!retrying[currentExercise?.id]);
let selectedChoice=$derived(drafts[currentExercise?.id]??progress.exercises[currentExercise?.id]?.attempts.at(-1)?.answer);
const restored=new Set<string>();
$effect(()=>{const id=currentExercise.id;untrack(()=>{if(restored.has(id))return;restored.add(id);const answer=progress.exercises[id]?.attempts.at(-1)?.answer;if(!answer)return;drafts={...drafts,[id]:answer};if(currentExercise.type==="matching"){try{matches={...matches,[id]:JSON.parse(answer)};}catch{/* Leave malformed legacy drafts untouched. */}}if(currentExercise.type==="order"){const remaining=[...(currentExercise.choices??[])];const selected:number[]=[];let rest=answer;while(rest){const i=remaining.findIndex(word=>word&&(rest===word||rest.startsWith(word+" ")));if(i<0)break;selected.push(i);rest=rest.slice(remaining[i].length).trimStart();remaining[i]="";}tokenSelections={...tokenSelections,[id]:selected};}});});
let answered=$derived(Object.values(progress.exercises).filter(e=>e.attempts.length).length);
const pending=new Map<string,{answer:string;id:string}>();
function chooseToken(index:number){const id=currentExercise.id;tokenSelections={...tokenSelections,[id]:[...(tokenSelections[id]??[]),index]};drafts={...drafts,[id]:tokenSelections[id].map(i=>currentExercise.choices![i]).join(" ")};}
function removeToken(position:number){const id=currentExercise.id;tokenSelections={...tokenSelections,[id]:(tokenSelections[id]??[]).filter((_,i)=>i!==position)};drafts={...drafts,[id]:tokenSelections[id].map(i=>currentExercise.choices![i]).join(" ")};}
function responseText(answer:string){if(currentExercise.type!=="matching")return answer;try{const pairs=JSON.parse(answer) as Record<string,string>;return (currentExercise.matchingPairs??[]).map(p=>`${p.text}: ${pairs[p.id]??""}`).join("; ");}catch{return answer;}}
async function submit(){if(submitting||busy)return;const exercise=currentExercise,answer=drafts[exercise.id];if(!answer?.trim())return;submitting=true;const prior=pending.get(exercise.id);const id=prior?.answer===answer?prior.id:crypto.randomUUID();pending.set(exercise.id,{answer,id});try{const result=await act({type:"answer",exerciseId:exercise.id,attemptId:id,answer,transliterationVisible:isArabic&&showTransliteration,supportUsed:inspected||transliterationUsed,evidenceVersion:2});if(result){pending.delete(exercise.id);retrying={...retrying,[exercise.id]:false};}}finally{submitting=false;}}
async function chooseAnswer(choice:string){if(submitted||submitting||busy)return;drafts={...drafts,[currentExercise.id]:choice};await submit();}
function retry(){retrying={...retrying,[currentExercise.id]:true};const next={...drafts};delete next[currentExercise.id];drafts=next;}

</script>
{#snippet sentence(item:CourseSentence)}
<div class="sentence"><CourseText text={item.text} {language} {showTransliteration} transliteration={item.transliteration} block/><CourseAudio {language} text={item.text} hideMissing/><p class="translation">{item.english}</p></div>
{/snippet}
<div class="exercise-column">
<div class="practice-tools"><label>Question <select aria-label="Question" value={exerciseIndex} onchange={e=>exerciseIndex=Number(e.currentTarget.value)}>{#each lesson.exercises as exercise,i}<option value={i}>{i+1} / {lesson.exercises.length} · {{choice:"Choose",recall:"Write",order:"Order",matching:"Match","self-check":"Compare"}[exercise.type]}{progress.exercises[exercise.id]?.attempts.length?" · attempted":""}</option>{/each}</select></label></div>
<section class="quiz" aria-label="Practice question">
<h2><CourseText text={currentExercise.prompt} {language} {showTransliteration}/></h2>
{#if currentExercise.promptAtom}<div class="sentence prompt"><CourseText text={currentExercise.promptAtom.text} {language} {showTransliteration} transliteration={currentExercise.promptAtom.transliteration} block/><CourseAudio {language} text={currentExercise.promptAtom.text} hideMissing/>{#if currentResult?.promptEnglish}<p class="translation">{currentResult.promptEnglish}</p>{/if}</div>{/if}
{#if currentExercise.supportAtoms?.length}<details class="examples" ontoggle={e=>{if(e.currentTarget.open)onSupportUsed();}}><summary>Examples</summary>{#each currentExercise.supportAtoms as support}{@render sentence(support)}{/each}</details>{/if}
{#if currentExercise.type === "matching"}
<div class="matching-pairs">{#each currentExercise.matchingPairs ?? [] as pair}<div class="matching-row"><div class="matching-source"><CourseText text={pair.text} {language} {showTransliteration} transliteration={pair.transliteration} block/><CourseAudio {language} text={pair.text} hideMissing/>{#if progress.exercises[currentExercise.id]?.attempts.at(-1)?.pairResults}{@const pairResult=progress.exercises[currentExercise.id].attempts.at(-1)?.pairResults?.find(p=>p.id===pair.id)}<small class:matched={pairResult?.correct}>{pairResult?.correct?"Matched":"Correct meaning"}{currentResult?.matchingAnswers?.[pair.id]?` · ${currentResult.matchingAnswers[pair.id]}`:""}</small>{/if}</div><select aria-label={`Meaning for ${pair.text}`} value={matches[currentExercise.id]?.[pair.id]??""} disabled={busy} onchange={event=>{const id=currentExercise!.id;matches={...matches,[id]:{...matches[id],[pair.id]:event.currentTarget.value}};drafts={...drafts,[id]:Object.keys(matches[id]).length===currentExercise!.matchingPairs!.length&&Object.values(matches[id]).every(Boolean)?JSON.stringify(matches[id]):""};}}><option value="">Choose a meaning</option>{#each currentExercise.choices??[] as meaning}<option value={meaning}>{meaning}</option>{/each}</select></div>{/each}</div>
{:else if currentExercise.type === "choice"}
<div class="choices" role="group" aria-label="Answer choices">{#each currentExercise.choices??[] as choice,index}<div class="choice-row" class:selected={selectedChoice===choice}><button class="choice" aria-pressed={selectedChoice===choice} disabled={busy||submitting||submitted} onclick={()=>chooseAnswer(choice)}><span class="option-index">{String.fromCharCode(65+index)}</span><span class="option-copy">{#if submitted&&currentResult?.correctChoices?.includes(choice)}<span class="choice-result">Correct answer</span>{:else if submitted&&selectedChoice===choice}<span class="choice-result">Your answer</span>{/if}<CourseText text={choice} {language} {showTransliteration} transliteration={currentExercise.choiceSupport?.[choice]?.transliteration} block/>{#if currentResult?.choiceSupport?.[choice]?.english}<small>{currentResult.choiceSupport?.[choice]?.english}</small>{/if}</span></button><CourseAudio {language} text={choice} hideMissing/></div>{/each}</div>
{:else if currentExercise.type === "order"}
<div class="answer-built" dir={isArabic?"rtl":"ltr"} aria-live="polite">{#if drafts[currentExercise.id]}{#each tokenSelections[currentExercise.id]??[] as tokenIndex,position}{@const token=currentExercise.choices![tokenIndex]}<button class="built-token" aria-label={`Remove ${token}`} onclick={()=>removeToken(position)}><CourseText text={token} {language} {showTransliteration} transliteration={currentExercise.choiceSupport?.[token]?.transliteration} block/></button>{/each}{:else}<span class="placeholder">Select the words below</span>{/if}</div>
<div class="tokens">{#each currentExercise.choices??[] as token,i}<div class="token"><button disabled={busy||tokenSelections[currentExercise.id]?.includes(i)} onclick={()=>chooseToken(i)}><CourseText text={token} {language} {showTransliteration} transliteration={currentExercise.choiceSupport?.[token]?.transliteration} block/></button><CourseAudio {language} text={token} hideMissing/></div>{/each}</div><button class="text-button" onclick={()=>{tokenSelections={...tokenSelections,[currentExercise!.id]:[]};drafts={...drafts,[currentExercise!.id]:""};}}>Clear sentence</button>
{:else if currentExercise.type === "self-check"}
<label class="answer-label" for="self-check-answer">Your response</label><textarea id="self-check-answer" class="answer-input" lang={language} rows="3" dir="auto" value={drafts[currentExercise.id]??""} oninput={event=>drafts={...drafts,[currentExercise!.id]:event.currentTarget.value}} placeholder="Write your response…"></textarea>
{:else}
<label class="answer-label" for="recall-answer">Your answer</label><input id="recall-answer" class="answer-input" lang={language} dir="auto" autocomplete="off" value={drafts[currentExercise.id]??""} oninput={event=>drafts={...drafts,[currentExercise!.id]:event.currentTarget.value}} onkeydown={event=>{if(event.key==="Enter")void submit();}} placeholder={isArabic?"Type Arabic or transliteration…":"Type your answer…"}/>
{/if}
<div class="quiz-actions">{#if currentExercise.type!=="choice"}<button class="primary" disabled={busy||!drafts[currentExercise.id]?.trim()} onclick={submit}>{progress.exercises[currentExercise.id]?.attempts.length?"Check practice answer":"Check answer"}</button>{:else if submitted}<button class="secondary" onclick={retry}>Try again</button>{/if}<button class="text-button" disabled={busy} onclick={()=>act({type:"hint",exerciseId:currentExercise!.id})}>Hint</button><button class="text-button" disabled={busy} onclick={()=>act({type:"reveal",exerciseId:currentExercise!.id})}>Show answer</button></div>
{#if currentResult}{@const result=currentResult}<div class="feedback" class:correct={result.correct===true} role="status"><strong>{result.correct==null?(result.answer?"Compare":"Hint"):result.correct?"Correct":"Try again"}</strong>
{#if currentExercise.type!=="choice" && result.correct!==true && progress.exercises[currentExercise.id]?.attempts.length}<p class="your-answer">Your response: <CourseText text={responseText(progress.exercises[currentExercise.id].attempts.at(-1)?.answer??"")} {language} {showTransliteration}/></p>{/if}
{#if (currentExercise.type==="choice"||currentExercise.type==="matching")}{:else if result.answerAtoms?.length}{#each result.answerAtoms as atom}{@render sentence(atom)}{/each}{:else if result.answer}<div class="feedback-answer"><CourseText text={result.answer} {language} {showTransliteration} block/>{#if language==="hu"||/[\u0600-\u06ff]/u.test(result.answer)}<CourseAudio {language} text={result.answer} hideMissing/>{/if}</div>{/if}
{#if result.text}<p><CourseText text={result.text} {language} {showTransliteration}/></p>{/if}{#if result.rubricText}<p class="rubric"><CourseText text={result.rubricText} {language} {showTransliteration}/></p>{/if}
{#if currentExercise.type === "self-check" && progress.exercises[currentExercise.id]?.attempts.length}<div class="self-assessment"><p>How did you do?</p>{#each [["again","Needs another try"],["close","Partly meets it"],["met","Meets the rubric"]] as option}<button class="secondary" disabled={busy} aria-pressed={progress.exercises[currentExercise.id].attempts.at(-1)?.selfAssessment===option[0]} onclick={()=>act({type:"self-assess",exerciseId:currentExercise!.id,assessment:option[0] as "again"|"close"|"met"})}>{option[1]}</button>{/each}</div>{/if}</div>{/if}
<div class="question-nav"><button class="secondary" disabled={exerciseIndex===0||busy} onclick={()=>exerciseIndex--}>Previous</button><span>{exerciseIndex+1} / {lesson.exercises.length}</span><button class="secondary" disabled={exerciseIndex===lesson.exercises.length-1||busy} onclick={()=>exerciseIndex++}>Next question</button></div>
</section>
</div>
<style>
.exercise-column{max-width:720px}.practice-tools{display:flex;gap:12px;margin:8px 0 12px}.practice-tools label{display:flex;align-items:center;gap:8px;font-size:14px}.practice-tools select{max-width:100%}.quiz h2{font-size:20px;line-height:1.45;font-weight:600;margin:0 0 12px;white-space:pre-line}.sentence{display:flex;flex-wrap:wrap;align-items:center;gap:4px 12px;margin:8px 0}.sentence .translation{flex-basis:100%;font-size:15px;line-height:1.5;color:#526057;margin:0}.prompt{margin-bottom:12px}.choices{display:grid;gap:6px;max-width:640px}.choice-row{display:flex;align-items:center;gap:8px;border:1px solid #c2cdc3;border-radius:4px;background:#fff;padding-right:8px}.choice-row.selected{background:#e7f0e9;border-color:#245c44;box-shadow:inset 3px 0 #245c44}.choice{display:flex;flex:1;align-items:center;gap:12px;min-width:0;min-height:48px;padding:7px 12px;text-align:left;border:0;background:none;color:inherit;font:inherit}.option-index{display:grid;place-items:center;flex:0 0 22px;height:22px;border:1px solid #a6b6a8;border-radius:50%;font-size:12px;color:#526057}.selected .option-index{background:#245c44;color:white;border-color:#245c44}.option-copy{min-width:0}.option-copy small{display:block;margin-top:2px;font-size:14px;color:#526057}.choice-row :global(.audio-controls){margin:0;flex-shrink:0;max-width:115px}.answer-label{display:block;font-size:14px;margin:0 0 5px}.answer-input{box-sizing:border-box;width:100%;padding:8px 10px;border:1px solid #84998c;border-radius:3px;background:#fff;font-size:20px;line-height:1.5;font-family:inherit}.answer-input[lang="ar-EG"]{font:26px/1.55 Tahoma,sans-serif}.answer-input::placeholder{font:16px/1.5 system-ui,sans-serif;color:#66726b}.built-token{background:white;border:1px solid #b2bcb5;border-radius:3px;padding:5px 8px;min-height:44px;font-size:18px}.answer-built{display:flex;align-items:center;flex-wrap:wrap;gap:6px;min-height:50px;padding:8px 10px;border:1px solid #a6b6a8;border-radius:3px;font-size:20px}.placeholder{font-size:15px;color:#66726b}.tokens{display:flex;gap:6px;flex-wrap:wrap;margin:8px 0 0}.token{display:flex;flex-direction:column;align-items:center}.token button{background:white;border:1px solid #b2bcb5;border-radius:3px;padding:5px 10px;min-height:44px;font-size:18px}.token :global(.audio-controls){margin:2px 0}.quiz-actions{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:12px}.primary,.secondary,select{padding:8px 12px;border:1px solid #84998c;border-radius:3px;background:white;color:#234b38;font:inherit;min-height:44px}.primary{background:#245c44;color:white;border-color:#245c44}.text-button{background:none;border:0;color:#245c44;min-height:44px;padding:6px 8px;font:inherit}.text-button:hover{background:#e7eee5}.feedback{padding:12px;margin-top:12px;background:#f7f3e9;border-left:3px solid #b4a279;line-height:1.5;max-width:640px}.feedback.correct{background:#edf3ed;border-color:#60846b}.feedback>p{margin:6px 0}.feedback .sentence{margin:6px 0}.feedback-answer{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;margin-top:6px;font-size:21px;white-space:pre-line}.your-answer{overflow-wrap:anywhere}.question-nav{display:flex;align-items:center;gap:12px;border-top:1px solid #d4d8d1;padding-top:12px;margin-top:20px}.question-nav span{font-size:13px;color:#526057}.question-nav button:last-child{margin-left:auto}.matching-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;align-items:center;padding:8px 0;border-bottom:1px solid #d4d8d1}.matching-source{display:flex;flex-wrap:wrap;align-items:center;gap:4px 10px}.matching-source small{font-size:13px;width:100%;color:#856831}.matching-source .matched{color:#245c44}.matching-row select{width:100%;min-width:0;font-size:15px}.self-assessment{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}.self-assessment p{width:100%;margin:0}.self-assessment [aria-pressed=true]{background:#d9e9dd}.examples{margin:8px 0 12px}.examples summary{cursor:pointer;min-height:36px;color:#245c44}.rubric{white-space:pre-line}.choice-result{display:block;font-size:12px;font-weight:600;color:#245c44}.choice:disabled{opacity:1;cursor:default}button:disabled{opacity:.5;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:2px solid #245c44;outline-offset:3px}
@media(max-width:600px){.quiz h2{font-size:18px}.choice-row{gap:4px;padding-right:5px}.choice{padding:6px 8px;gap:8px}.choice-row :global(.audio-controls){flex-direction:column;gap:3px;max-width:58px}.matching-row{gap:8px}.primary,.secondary{padding:8px 10px}.quiz-actions{gap:4px}.practice-tools select{min-width:0}.question-nav{gap:8px}}
</style>
